mapper.select:
SELECT id, user_id, image_path, status, identity_id, confidence, heatmap_path, type, operation_status, individual_id, created_at, updated_at
FROM recognition_record
WHERE id = #{id}

SELECT id, user_id, image_path, status, identity_id, confidence, heatmap_path, type, operation_status, individual_id, created_at, updated_at
FROM recognition_record


        AND type = #{type}


        AND created_at >= #{startTime}


        AND created_at <= #{endTime}


        AND id = #{recordId}


ORDER BY created_at DESC
